// T-347: goldens for the online-helper answers: the ask-llm-ux section 5
// examples and each D-93 band, ar/en x light/dark, plus the invest rows at
// 130%. Tagged; PNGs are generated by CI and not committed from a local run.
@Tags(['golden'])
library;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zaghlol/features/ask/application/llm_ask_flow.dart';
import 'package:zaghlol/features/ask/presentation/ask_screen.dart';

import 'llm_answer_fixtures.dart';
import 'llm_answer_views_test.dart' show pumpAnswer, views;

void main() {
  final cases = <String, AskLlmAnswered>{
    'whatif': answered(whatIfAnswer, plan: whatIfPlan),
    'average': answered(averageAnswer),
    'compare': answered(compareAnswer),
    'suggest': answered(suggestAnswer),
    'invest_gold': answered(investAnswer(450000)),
    'invest_stocks': answered(investAnswer(50000)),
    'invest_small': answered(investAnswer(5000)),
    'invest_nothing': answered(investAnswer(0)),
  };
  for (final locale in const [Locale('ar', 'EG'), Locale('en')]) {
    for (final dark in const [false, true]) {
      final name = '${locale.languageCode}_${dark ? 'dark' : 'light'}';
      for (final e in cases.entries) {
        testWidgets('S-50 answer ${e.key} $name', (t) async {
          await pumpAnswer(
            t,
            e.value,
            locale: locale,
            dark: dark,
            extra: views(),
          );
          await expectLater(
            find.byType(AskScreen),
            matchesGoldenFile('goldens/ask_llm_answer_${e.key}_$name.png'),
          );
        });
      }
      testWidgets('S-50 answer invest gold 130 $name', (t) async {
        await pumpAnswer(
          t,
          cases['invest_gold']!,
          locale: locale,
          dark: dark,
          scale: 1.3,
          extra: views(),
        );
        await expectLater(
          find.byType(AskScreen),
          matchesGoldenFile('goldens/ask_llm_answer_invest130_$name.png'),
        );
      });
    }
  }
}
